D=load(); demos=D['demonstrations']
xs=[21,26,31,36,41]
def sw(b,y): return [b[y][x] for x in xs]
def bits(v): return sum((c==1)<<(4-i) for i,c in enumerate(v))
for i,t in enumerate(demos):
 st=t['start']; en=t['steps'][-1].get('board')
 print(i+1,'init top',sw(st,42),bits(sw(st,42)),'bot',sw(st,44),bits(sw(st,44)))
 print('final top',sw(en,42),bits(sw(en,42)),'bot',sw(en,44),bits(sw(en,44)))
 print('actions',[s['actions'] for s in t['steps']])
 # blue columns by row groups
 blues={}
 for y,row in enumerate(en):
  for x,c in enumerate(row):
   if c==11: blues.setdefault(y,[]).append(x)
 print('final blue ranges',[(y,min(x),max(x)) for y,x in blues.items()])

def final(t):
 b=[r[:] for r in t['start']]
 for s in t['steps']:
  for x,y,c in s['changes']: b[y][x]=c
 return b
for i,t in enumerate(demos):
 st=t['start']; en=final(t)
 print(i+1,'init',sw(st,42),bits(sw(st,42)),sw(st,44),bits(sw(st,44)),'final',sw(en,42),bits(sw(en,42)),sw(en,44),bits(sw(en,44)))
 blues={}
 for y,row in enumerate(st):
  for x,c in enumerate(row):
   if c==11: blues.setdefault(y,[]).append(x)
 print('initial blue ranges',[(y,min(x),max(x)) for y,x in blues.items()])

